-- Storage Slip eligibility for the Mog Storage container (2).
--
-- The 33 slips and the item ids each accepts are game data, cross-checked
-- against https://www.bg-wiki.com/ffxi/Category:Storage_Slip and the public
-- Windower resources slip table (BSD-3-Clause). Only item ids and slip numbers
-- are stored here; no Windower code is copied.

CREATE TABLE IF NOT EXISTS item_storage (
    item_id INTEGER PRIMARY KEY,
    slip    INTEGER NOT NULL
);

