-- The first version of this feature used the Mog Locker (container 4) by
-- mistake.  Move those rows into Storage so nobody has to hunt for gear in a
-- container this server never opens.  Existing Storage rows keep their slots;
-- legacy rows take the free slots after them, and anything that does not fit
-- stays in container 4.
CREATE TEMP TABLE _storage_free_slots (slot INTEGER PRIMARY KEY);
WITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM seq WHERE n < 80)
INSERT INTO _storage_free_slots SELECT n FROM seq;

CREATE TEMP TABLE _storage_legacy AS
SELECT character_id, slot AS old_slot,
       ROW_NUMBER() OVER (PARTITION BY character_id ORDER BY slot) AS rn
FROM char_inventory WHERE container = 4;

CREATE TEMP TABLE _storage_free AS
SELECT c.character_id, s.slot AS new_slot,
       ROW_NUMBER() OVER (PARTITION BY c.character_id ORDER BY s.slot) AS rn
FROM (SELECT DISTINCT character_id FROM _storage_legacy) c
CROSS JOIN _storage_free_slots s
WHERE s.slot NOT IN (
    SELECT c2.slot FROM char_inventory c2
    WHERE c2.character_id = c.character_id AND c2.container = 2);

UPDATE char_inventory
SET container = 2,
    slot = (SELECT f.new_slot
            FROM _storage_legacy l JOIN _storage_free f
              ON f.character_id = l.character_id AND f.rn = l.rn
            WHERE l.character_id = char_inventory.character_id
              AND l.old_slot = char_inventory.slot)
WHERE container = 4
  AND EXISTS (SELECT 1
              FROM _storage_legacy l JOIN _storage_free f
                ON f.character_id = l.character_id AND f.rn = l.rn
              WHERE l.character_id = char_inventory.character_id
                AND l.old_slot = char_inventory.slot);

DROP TABLE _storage_free;
DROP TABLE _storage_legacy;
DROP TABLE _storage_free_slots;
